from content.authoring import E, J, L, P, Q, R, T
from content.units.input_text import SCANNER

METHOD_TOTAL = J('Scanner in = new Scanner(System.in);\nint count = in.nextInt();\nSystem.out.println(total(count, 120));', SCANNER, 'static int total(int count, int unitPrice) {\n    return count * unitPrice;\n}')
REF_SCOPE = J('int value = 5;\nbump(value);\nSystem.out.println(value);\nvalue = bump(value);\nSystem.out.println(value);', members='static int bump(int value) {\n    return value + 1;\n}')
EXCEPTIONS = J('Scanner in = new Scanner(System.in);\nwhile (in.hasNextLine()) {\n    String line = in.nextLine().trim();\n    if (line.equals("q")) break;\n    try {\n        int count = Integer.parseInt(line);\n        if (count < 1 || count > 100) throw new IllegalArgumentException("range");\n        System.out.println("Accepted: " + count);\n    } catch (NumberFormatException error) {\n        System.out.println("Invalid number");\n    } catch (IllegalArgumentException error) {\n        System.out.println("Invalid range");\n    }\n}', SCANNER)
VALIDATE = J('Scanner in = new Scanner(System.in);\nString title = in.nextLine().trim();\nif (validTitle(title)) System.out.println("Accepted");\nelse System.out.println("Invalid");', SCANNER, 'static boolean validTitle(String title) {\n    return !title.isEmpty() && title.length() <= 20 && !title.contains("|");\n}')
DISCOUNT = J('Scanner in = new Scanner(System.in);\nif (!in.hasNextInt()) { System.out.println("Invalid"); return; }\nint count = in.nextInt();\nif (count < 1 || count > 100) { System.out.println("Invalid"); return; }\nSystem.out.println(price(count));', SCANNER, 'static int price(int count) {\n    int total = count * 100;\n    if (count >= 5) total -= 20;\n    return total;\n}')

LESSONS = [
L('methods-and-parameters', 'Small Methods with Inputs & Results', 'Give a reusable operation a clear contract.',
  ['A method groups an operation under a name. Parameters describe the inputs it receives. A return type describes the value it produces; return sends that value to the caller and ends the method. void means no returned value.',
   'Our first helper methods are static so main can call them without constructing an object. Define them inside Main but outside main. A method call does not automatically display its return value; the caller chooses whether to print or store it.',
   'Keep calculation separate from input and printing. A total(count, unitPrice) method can then serve both a ticket workflow and a parcel workflow. Its contract should state valid inputs; validation may belong to the caller or the method, but the responsibility must be explicit.'],
  ['Declare and call a method with parameters.', 'Use a returned value without coupling calculation to console input.'],
  E(METHOD_TOTAL, '360\n', ['Read count 3.', 'Call total with count and price.', 'The helper returns a product.', 'The caller prints the return value.'], '3\n'),
  Q('For input 2, what does the worked program print?', METHOD_TOTAL, '240', 'count and 120 are arguments; the method multiplies them and returns 240.'),
  R('Why should total accept count and price rather than read Scanner or print inside the method?', 'Explicit parameters make the calculation reusable and testable. Returning the result lets callers choose input and output behavior.', ['I identify the two method inputs and result.', 'I separate calculation from console interaction.']),
  P('Read two valid int values width and height from 0..100. Implement static int area(int width, int height), return their product, and print it from main.', J('Scanner in = new Scanner(System.in);\nint width = in.nextInt(), height = in.nextInt();\nSystem.out.println(area(width, height));', SCANNER, 'static int area(int width, int height) {\n    return width * height;\n}'), [T('rectangle', '4 7\n', '28\n'), T('zero width', '0 7\n', '0\n'), T('one square', '1 1\n', '1\n')], starter=J('Scanner in = new Scanner(System.in);\n// Read dimensions, call area, then print its result.', SCANNER), rubric=['area uses two parameters and returns int.', 'Only main reads and prints; the helper calculates.']),
  diagram={'kind':'sequence','nodes':['Caller: total(3, 120)','Parameters: count=3, price=120','Return product','Caller prints result'],'edges':[[0,1],[1,2],[2,3]]}),
L('method-scope', 'Scope & Pass-by-Value', 'Know which variable a method can actually change.',
  ['Local variables belong to their declaring block or method. A parameter is local to the called method. Two methods can each have a variable named value without sharing that local storage.',
   'Java passes argument values by value. For int, the helper receives a copy of the integer value. Assigning a parameter or returning a new value does not update the caller’s local variable unless the caller stores that returned value.',
   'For objects, Java still passes a copied reference value, not the caller’s variable itself. Object state can be mutated through a copied reference; object lessons will show that separately. Do not describe Java as pass-by-reference.'],
  ['Trace separate caller and parameter values.', 'Store a returned result when an update is intended.'],
  E(REF_SCOPE, '5\n6\n', ['The first bump result is ignored.', 'The caller’s value remains 5.', 'The second call’s result is assigned back.', 'The caller now stores 6.']),
  Q('Write both output lines for this example.', J('int n = 2;\nchange(n);\nSystem.out.println(n);\nSystem.out.println(change(n));', members='static int change(int n) { return n + 3; }'), '2\n5', 'The ignored return cannot replace caller n; the second println displays the returned copy’s calculation.'),
  R('Does assigning a method’s int parameter change the caller’s int variable? Explain the required update.', 'No. The parameter contains a copy. Return the changed value and assign it to the caller’s variable if that update is intended.', ['I identify separate local variables.', 'I state Java pass-by-value.', 'I explicitly assign the returned value at the caller.']),
  P('Read one valid int n in 0..100. Use static int increment(int n) returning n + 1. Assign the returned value back in main, then print it.', J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\nn = increment(n);\nSystem.out.println(n);', SCANNER, 'static int increment(int n) { return n + 1; }'), [T('ordinary update', '4\n', '5\n'), T('zero update', '0\n', '1\n')], starter=J('Scanner in = new Scanner(System.in);\nint n = in.nextInt();\n// Define the helper and store its returned result.', SCANNER), rubric=['I return an updated value from increment.', 'I assign that return value before printing.'])),
L('exception-handling', 'Specific Failures, Useful Recovery', 'Catch what you can handle without hiding programming errors.',
  ['An exception interrupts the normal path. A matching catch handles it; execution does not resume at the failed statement. Catch close to a boundary where you can choose a useful response, such as converting a user-entered line.',
   'NumberFormatException is a subtype of IllegalArgumentException. If you need distinct messages, catch the more specific type first. A broad superclass catch placed first would make the subtype catch unreachable.',
   'Catch a conversion problem to let the next request run. Do not catch Exception around everything and print Success: that hides programming mistakes and file failures. Resource cleanup belongs in try-with-resources for closable file handles, which the persistence stage will teach.'],
  ['Trace which specific catch handles a failure.', 'Preserve useful errors and continue after recoverable bad input.'],
  E(EXCEPTIONS, 'Invalid number\nInvalid range\nAccepted: 2\n', ['pear fails conversion.', '0 parses but violates the range.', '2 follows the valid path after both errors.'], 'pear\n0\n2\nq\n'),
  Q('For input -1 then q, what exact output is produced?', EXCEPTIONS, 'Invalid range', '-1 parses successfully; the explicit range failure is an IllegalArgumentException, not a NumberFormatException.'),
  R('Why is a single catch(Exception) that always prints Success a bad input handler?', 'It misreports failures and can hide unrelated programming errors. Catch the failure you can meaningfully handle and give a truthful result.', ['I distinguish conversion, validation and unrelated failures.', 'I keep the user message truthful.', 'I preserve later valid requests.']),
  P('Process one whole line at a time until q/EOF. Accept integers 1..10 and print Accepted: n. Print Invalid number for failed conversion and Invalid range for parsed values outside the range. Continue after both errors.', J(EXCEPTIONS.split('    public static void main(String[] args) {\n',1)[1].rsplit('\n    }',1)[0].replace('count > 100','count > 10'), SCANNER), [T('distinct recovery', 'pear\n0\n2\nq\n', 'Invalid number\nInvalid range\nAccepted: 2\n'), T('overflow and upper boundary', '99999999999999999\n10\n11\nq\n', 'Invalid number\nAccepted: 10\nInvalid range\n')], starter=J('Scanner in = new Scanner(System.in);\n// Consume each line, catch conversion separately, validate and retry.', SCANNER))),
L('validation-methods', 'Refactor a Validation Rule', 'Keep one named rule reusable and independent of console I/O.',
  ['A boolean method expresses a yes/no rule. validTitle can take a String and return whether it fits a format. The caller handles the user message and decides whether to stop, retry or save a record.',
   'Validate after the agreed normalization. Here the caller trims ends, then the helper rejects empty text, length greater than 20, and the delimiter |. Rejecting the delimiter will matter when records are stored in a simple line format.',
   'A reusable validation method must not silently change the caller’s input or print different messages. Give it an explicit contract. Testing the boundary and the forbidden delimiter is more informative than repeating one good title.'],
  ['Write a pure boolean validation helper.', 'Test empty, maximum length and forbidden characters.'],
  E(VALIDATE, 'Accepted\n', ['The caller trims Orbit.', 'The helper checks all three rules.', 'The caller chooses the displayed message.'], ' Orbit \n'),
  Q('For input containing a single |, what does the worked example print?', VALIDATE, 'Invalid', 'The delimiter rule is false even though the text is nonempty and short.'),
  R('What belongs in validTitle, and what belongs in its caller?', 'The helper checks the stated text rules and returns boolean. The caller reads/normalizes input, handles retry or exit, and prints the user-facing result.', ['I keep input/output outside the helper.', 'I state every format rule.', 'I test a boundary and forbidden delimiter.']),
  P('Implement validTitle(String): reject empty text, more than 20 UTF-16 code units, or |. Read and trim one supplied line; print Accepted or Invalid from main.', VALIDATE, [T('ordinary title', 'Orbit\n', 'Accepted\n'), T('blank', ' \n', 'Invalid\n'), T('delimiter', 'A|B\n', 'Invalid\n'), T('length twenty', 'abcdefghijklmnopqrst\n', 'Accepted\n'), T('length twenty-one', 'abcdefghijklmnopqrstu\n', 'Invalid\n')], starter=J('Scanner in = new Scanner(System.in);\nString title = in.nextLine().trim();\n// Call your pure validation helper and print its boolean decision as a label.', SCANNER), rubric=['The helper checks all three rules and returns boolean.', 'Only main reads, trims and prints.'])),
L('debugging-testing', 'Test the Rule, Not Your Hope', 'Use normal, boundary and failure cases to locate a logic defect.',
  ['A useful test records input, expected output, actual output and the reason the case matters. Derive expected results from the requirement before looking at your program. Otherwise you risk approving the same misunderstanding twice.',
   'For a threshold at five items, test four, five and six. A wrong > versus >= may pass a middle case and fail the exact boundary. Reduce a failure to the smallest input that exposes it, trace the relevant values, and repair one cause.',
   'Regression tests keep earlier behavior correct after a repair. Passing supplied checks does not prove all inputs correct. Add a new case when you discover a defect and explain the requirement it protects.'],
  ['Construct a requirements-based test table.', 'Reproduce a boundary bug and verify its repair.'],
  E(DISCOUNT, '480\n', ['Validate the count.', 'Calculate count × 100.', 'At count >= 5 apply a fixed total discount of 20.', 'Return the final total.'], '5\n'),
  Q('At count 4, what exact total is printed by the worked program?', DISCOUNT, '400', 'Four is below the discount threshold, so the total is unchanged.'),
  R('Design a minimal test table for the five-item discount rule, including an invalid count.', 'Use 4 → 400, 5 → 480, 6 → 580 and 0 → Invalid. The middle threshold case catches > versus >=.', ['I include below, at and above the threshold.', 'I include invalid input.', 'I derive expected totals from the rule.']),
  P('Read a whole integer token; accept counts 1..100. Price is 100 per item with a fixed total discount of 20 when count >= 5. Print Invalid for bad/out-of-range input; otherwise print the final integer total. Use a separate price method.', DISCOUNT, [T('below discount', '4\n', '400\n'), T('at discount', '5\n', '480\n'), T('above discount', '6\n', '580\n'), T('invalid boundary', '0\n', 'Invalid\n'), T('bad token', 'pear\n', 'Invalid\n')], starter=J('Scanner in = new Scanner(System.in);\n// Validate the count, then call a price helper and print its result.', SCANNER), rubric=['My test table includes the exact threshold.', 'My calculation is in a method separate from reading/printing.']),
  extra_practice=P('Repair the > threshold bug so the discount also applies at exactly five.', DISCOUNT, [T('threshold regression', '5\n', '480\n'), T('below threshold unchanged', '4\n', '400\n')], starter=DISCOUNT.replace('count >= 5','count > 5'), kind='repair')),
]
